interface Raw {
  status: number;
  body: string;
}

// Raw request so we can forge Host / Content-Type independent of the socket we
// actually connect to (always 127.0.0.1).
function rawTo(
  toPort: number,
  opts: {
    method: string;
    path: string;
    headers?: Record<string, string>;
    body?: string;
  },
): Promise<Raw> {
  return new Promise<Raw>((resolve, reject) => {
    const req = httpRequest(
      {
        host: "127.0.0.1",
        port: toPort,
        method: opts.method,
        path: opts.path,
        headers: opts.headers ?? {},
      },
      (res: IncomingMessage) => {
        const chunks: Buffer[] = [];
        res.on("data", (c: Buffer) => chunks.push(c));
        res.on("end", () =>
          resolve({
            status: res.statusCode ?? 0,
            body: Buffer.concat(chunks).toString("utf8"),
          }),
        );
      },
    );
    req.on("error", reject);
    if (opts.body !== undefined) req.write(opts.body);
    req.end();
  });
}

// Convenience for the kernel server (module-scoped `port`).
function raw(opts: {
  method: string;
  path: string;
  headers?: Record<string, string>;
  body?: string;
}): Promise<Raw> {
  return rawTo(port, opts);
}

const validObserve = JSON.stringify({
  hookType: "post_tool_use",
  sessionId: "s-sec",
  project: "proj-sec",
  cwd: "/work/proj-sec",
