      verdict: "cosmetic",
    });
    const stored = await kv.get<Memory>(KV.memories, record.id);
    expect(stored?.provenance?.fileHashes).toEqual(record.fileHashes);
    expect(stored?.provenance?.fileHashesNormalized).toEqual(
      record.fileHashesNormalized,
    );
    expect(classifyProvenance(stored?.provenance, repoA).status).toBe(
      "cosmetic",
    );
  });

  it("rejects caller-claimed verification when hashes do not match, even via the core id", async () => {
    const record = canonRecord(repoA, "mem_forged");
    const forged = {
      ...record,
      fileHashes: { "src/source.ts": "b".repeat(64) },
      fileHashesNormalized: { "src/source.ts": "c".repeat(64) },
      verified: true,
      verdict: "verified",
    };

    const response = await post("/canon/import", { root: repoA, record: forged });
    expect(response.status).toBe(409);
    expect(await response.json()).toMatchObject({
      ok: false,
      code: "hash_mismatch",
    });
    expect(await kv.get(KV.memories, record.id)).toBeNull();

    const direct = await sdk.trigger<
      { root: string; record: unknown },
      { ok: boolean; code?: string }
    >({
      function_id: "mem::canon-import",
      payload: { root: repoA, record: forged },
    });
    expect(direct).toMatchObject({ ok: false, code: "hash_mismatch" });
    expect(await kv.get(KV.memories, record.id)).toBeNull();

    const inconsistent = {
      ...record,
      id: "mem_inconsistent_normalized",
      fileHashesNormalized: { "src/source.ts": "d".repeat(64) },
    };
    const inconsistentResponse = await post("/canon/import", {
      root: repoA,
      record: inconsistent,
    });
    expect(inconsistentResponse.status).toBe(409);
    expect(await inconsistentResponse.json()).toMatchObject({
      ok: false,
      code: "hash_mismatch",
    });
  });

  it("rejects a valid record from a different project identity", async () => {
    const record = canonRecord(repoA, "mem_wrong_project");
    const response = await post("/canon/import", { root: repoB, record });
    expect(response.status).toBe(409);
    expect(await response.json()).toMatchObject({
      ok: false,
      code: "project_mismatch",
    });
    expect(await kv.get(KV.memories, record.id)).toBeNull();
  });

  it("keeps both Canon routes behind the existing bearer-secret gate", async () => {
    expect((await post("/canon/export", { root: repoA }, false)).status).toBe(401);
    expect(
      (await post("/canon/import", { root: repoA, record: canonRecord(repoA) }, false))
        .status,
    ).toBe(401);
  });
});

//
// MCP server integration. Boots the full stack on an ephemeral port (the
// same wiring as e2e) and drives the dependency-free MCP dispatcher against
// it: initialize handshake, tool listing, and every tool round-trip
// including the memwarden-only memory_verify and memory_stats. No external
// host, no MCP SDK — pure offline.

import { createHash } from "node:crypto";
import { mkdtempSync, realpathSync, rmSync, writeFileSync } from "node:fs";
import { mkdir, mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  registerWorker,
  startHttpServer,
  __resetKernelSingleton,
  type Kernel,
  type RunningHttpServer,
} from "../src/kernel/index.js";
import { StoreLibsql } from "../src/state/store-libsql.js";
import { StateKV } from "../src/state/kv.js";
import { KV } from "../src/state/schema.js";
import { registerCoreFunctions, getSearchIndex } from "../src/functions/index.js";
import type { Memory } from "../src/functions/types.js";
import { registerApiTriggers } from "../src/triggers/api.js";
import { createMcpServer } from "../src/mcp/server.js";

let sdk: Kernel;
let store: StoreLibsql;
let kv: StateKV;
let http: RunningHttpServer;
let server: ReturnType<typeof createMcpServer>;
let baseUrl: string;
const testDirs: string[] = [];

beforeEach(async () => {
  __resetKernelSingleton();
  getSearchIndex().clear();
  store = new StoreLibsql({ url: ":memory:" });
  sdk = registerWorker("in-process", { workerName: "memwarden-mcp" }, { store });
  kv = new StateKV(sdk);
  registerCoreFunctions(sdk, kv);
  registerApiTriggers(sdk);
  http = startHttpServer(sdk, { port: 0 });
  await new Promise<void>((r) => {
    if (http.server.listening) r();
    else http.server.once("listening", () => r());
  });
  const addr = http.server.address();
  const port = typeof addr === "object" && addr ? addr.port : 0;
  baseUrl = `http://127.0.0.1:${port}`;
  server = createMcpServer({ baseUrl });
});

afterEach(async () => {
  for (const dir of testDirs.splice(0))
    rmSync(dir, { recursive: true, force: true });
  await http.close().catch(() => undefined);
  await sdk.shutdown();
  __resetKernelSingleton();
});

function call(method: string, params?: unknown, id: number | null = 1) {
  return server.dispatch({ jsonrpc: "2.0", id, method, params });
}

function toolJson(response: Awaited<ReturnType<typeof call>>): Record<string, unknown> {
  const text = (
    response!.result as { content: Array<{ text: string }> }
  ).content[0]!.text;
  return JSON.parse(text) as Record<string, unknown>;
}

function tempProject(): string {
  const project = realpathSync(mkdtempSync(join(tmpdir(), "memwarden-mcp-search-")));
  testDirs.push(project);
  return project;
}

async function observeOverHttp(
  project: string,
  data: Record<string, unknown>,
  sessionId: string,
  timestamp = "2026-08-24T12:00:00.000Z",
): Promise<void> {
  const res = await fetch(`${baseUrl}/memwarden/observe`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      hookType: "post_tool_use",
      sessionId,
      project,
      cwd: project,
      timestamp,
      data,
    }),
  });
  expect(res.status).toBe(201);
  await res.text();
}

async function mcpSearch<T>(
  client: ReturnType<typeof createMcpServer>,
  args: Record<string, unknown>,
): Promise<T> {
  const response = await client.dispatch({
    jsonrpc: "2.0",
    id: 90,
    method: "tools/call",
    params: { name: "memory_search", arguments: args },
  });
  const result = response!.result as {
    isError?: boolean;
    content: Array<{ text: string }>;
  };
  expect(result.isError).not.toBe(true);
  return JSON.parse(result.content[0]!.text) as T;
}

describe("MCP handshake and tool listing", () => {
  it("initialize returns protocol + serverInfo", async () => {
    const res = await call("initialize");
    expect(res).not.toBeNull();
