      http_method: "POST",
      middleware_function_ids: ["middleware::api-auth"],
    },
  });

  // --- POST /memwarden/compact --------------------------------------
  // One-shot oplog migration + shrink: re-chain every entry as chain v2,
  // erase the payloads of forget-deleted records, anchor the old head hash
  // in a compact record, VACUUM. Auth'd: it rewrites the brain's history
  // file. dry_run reports what would happen without writing.
  //
  // prune_history additionally nulls SUPERSEDED payloads (older versions of
  // keys that were rewritten) — the storage lever, since a mature oplog is
  // mostly outdated versions. keep_days holds a recency window back in full;
  // the cutoff is resolved HERE, against the daemon clock that stamped every
  // oplog ts, rather than trusting a caller-supplied timestamp.
  interface CompactBody {
    dry_run?: boolean;
    dryRun?: boolean;
    prune_history?: boolean;
    keep_days?: number;
  }
  const DEFAULT_KEEP_DAYS = 7;
  sdk.registerFunction(
    "api::compact",
    async (req: ApiRequest<CompactBody>): Promise<Response> => {
      const body = (req.body ?? {}) as CompactBody;
      const prune = body.prune_history === true;
      // A bad keep_days must NOT silently fall back to the default: the caller
      // would believe it pruned with a window it never got.
      if (
        body.keep_days !== undefined &&
        (typeof body.keep_days !== "number" ||
          !Number.isFinite(body.keep_days) ||
          body.keep_days < 0)
      ) {
        return {
          status_code: 400,
          body: { error: "keep_days must be a number >= 0" },
        };
      }
      const keepDays = body.keep_days ?? DEFAULT_KEEP_DAYS;
      let result: unknown;
      try {
        result = await sdk.trigger({
          function_id: "state::compact",
          payload: {
            dryRun: body.dry_run === true || body.dryRun === true,
            ...(prune
              ? {
                  pruneSuperseded: true,
                  keepPayloadsSince: new Date(
                    Date.now() - keepDays * 86_400_000,
                  ).toISOString(),
                }
              : {}),
          },
        });
      } catch (err) {
        // A broken chain is refused, not re-anchored (see OplogChainBrokenError).
        if (err instanceof OplogChainBrokenError) {
          return { status_code: 409, body: { error: err.message, brokenAt: err.brokenAt } };
        }
        throw err;
      }
      const dryRun = body.dry_run === true || body.dryRun === true;
      if (!dryRun) {
        // Best-effort bookkeeping for `status`; never fails the compaction.
        // The db size right after compaction lets `status` tell growth since
        // then from the floor compaction cannot go below (the chain keeps one
        // hashed row per write, forever, for tamper-evidence).
        let dbBytes: number | null = null;
        try {
          dbBytes = statSync(join(getDataDir(), "memwarden.db")).size;
        } catch {
          dbBytes = null;
        }
        await new StateKV(sdk)
          .set(KV.maintenance, "compact", {
            at: new Date().toISOString(),
            pruned: prune,
            keepDays: prune ? keepDays : null,
            dbBytes,
          })
          .catch(() => undefined);
      }
      return { status_code: 200, body: result };
    },
  );
  sdk.registerTrigger({
    type: "http",
    function_id: "api::compact",
    config: {
      api_path: "/memwarden/compact",
      http_method: "POST",
      middleware_function_ids: ["middleware::api-auth"],
    },
  });

  // --- POST /memwarden/dejafix/lookup -----------------------------
  // Déjà Fix: surface source-current fixes for an error any agent already
  // solved. Raw-verified and cosmetic-current fixes pass; stale fixes never do.
  // cwd is both the project firewall and the checkout used for classification.
  sdk.registerFunction(
    "api::dejafix-lookup",
    async (
      req: ApiRequest<{ error_text?: string; errorText?: string; cwd?: string }>,
    ): Promise<Response> => {
      const body = (req.body ?? {}) as {
        error_text?: string;
        errorText?: string;
        cwd?: string;
      };
      const errorText =
        asNonEmptyString(body.error_text) ?? asNonEmptyString(body.errorText);
      if (!errorText) {
        return { status_code: 400, body: { error: "error_text is required" } };
      }
      const cwd = asNonEmptyString(body.cwd);
      if (!cwd) {
        return {
          status_code: 400,
          body: { error: "cwd is required (the repo to verify fixes against)" },
        };
      }
      const result = await sdk.trigger({
        function_id: "mem::dejafix_lookup",
        payload: { errorText, cwd },
      });
      return { status_code: 200, body: result };
    },
  );
  sdk.registerTrigger({
    type: "http",
    function_id: "api::dejafix-lookup",
    config: {
      api_path: "/memwarden/dejafix/lookup",
      http_method: "POST",
      middleware_function_ids: ["middleware::api-auth"],
    },
  });

  // --- POST /memwarden/dejafix/record -----------------------------
  // Record a {error -> root cause + fix} so any agent that hits the same error
  // later gets it back. Referenced files are hashed now so drift is detectable.
  sdk.registerFunction(
    "api::dejafix-record",
    async (
      req: ApiRequest<{
        error_text?: string;
        errorText?: string;
        signature?: string;
        fix?: string;
        root_cause?: string;
        rootCause?: string;
        files?: unknown;
        cwd?: string;
        tool?: string;
        session_id?: string;
        sessionId?: string;
      }>,
    ): Promise<Response> => {
      const body = (req.body ?? {}) as Record<string, unknown>;
      const fix = asNonEmptyString(body["fix"]);
      if (!fix) {
        return { status_code: 400, body: { error: "fix is required" } };
      }
      const cwd = asNonEmptyString(body["cwd"]);
      if (!cwd) {
        return { status_code: 400, body: { error: "cwd is required" } };
      }
      const errorText =
        asNonEmptyString(body["error_text"]) ??
        asNonEmptyString(body["errorText"]);
      const signature = asNonEmptyString(body["signature"]);
      if (!errorText && !signature) {
        return {
          status_code: 400,
          body: { error: "error_text or signature is required" },
        };
      }
      const files = Array.isArray(body["files"])
        ? (body["files"] as unknown[]).filter(
            (f): f is string => typeof f === "string" && f.trim().length > 0,
          )
        : undefined;
      const payload: Record<string, unknown> = { fix, cwd };
      if (errorText) payload["errorText"] = errorText;
      if (signature) payload["signature"] = signature;
      const rootCause =
        asNonEmptyString(body["root_cause"]) ??
        asNonEmptyString(body["rootCause"]);
      if (rootCause) payload["rootCause"] = rootCause;
      if (files && files.length > 0) payload["files"] = files;
      const tool = asNonEmptyString(body["tool"]);
      if (tool) payload["tool"] = tool;
      const sessionId =
        asNonEmptyString(body["session_id"]) ??
        asNonEmptyString(body["sessionId"]);
      if (sessionId) payload["sessionId"] = sessionId;

      const result = await sdk.trigger({
        function_id: "mem::dejafix_record",
        payload,
      });
      return { status_code: 200, body: result };
    },
  );
  sdk.registerTrigger({
    type: "http",
    function_id: "api::dejafix-record",
    config: {
      api_path: "/memwarden/dejafix/record",
      http_method: "POST",
      middleware_function_ids: ["middleware::api-auth"],
    },
  });

  // --- GET /memwarden/export --------------------------------------
  // Portability: a self-contained Brain Bundle the user can move between
  // machines or agents. No vendor in the loop.
  sdk.registerFunction(
    "api::export",
    async (): Promise<Response> => {
      const bundle = await exportBundle(new StateKV(sdk));
      return {
        status_code: 200,
        body: { ...bundle, exportedAt: new Date().toISOString() },
      };
    },
  );
  sdk.registerTrigger({
    type: "http",
    function_id: "api::export",
    config: {
      api_path: "/memwarden/export",
      http_method: "GET",
      middleware_function_ids: ["middleware::api-auth"],
    },
  });

  // --- POST /memwarden/import -------------------------------------
  sdk.registerFunction(
    "api::import",
    async (req: ApiRequest<unknown>): Promise<Response> => {
      const body = req.body;
      if (!isBrainBundle(body)) {
        return {
          status_code: 400,
          body: { error: "body is not a valid memwarden brain bundle" },
        };
      }
      try {
        const counts = await importBundle(new StateKV(sdk), body);
        return { status_code: 200, body: { imported: counts } };
      } catch (err) {
        return {
          status_code: 400,
          body: { error: err instanceof Error ? err.message : String(err) },
        };
      }
    },
  );
  sdk.registerTrigger({
    type: "http",
    function_id: "api::import",
    config: {
      api_path: "/memwarden/import",
      http_method: "POST",
      middleware_function_ids: ["middleware::api-auth"],
    },
  });
}

// Vitest configuration. The defaults already work, but this pins four things
// the suite relies on:
//
//   - include: only the `test/` directory (no stray src spec discovery).
//   - pool "forks": run each test FILE in its own child process. Several
//     modules expose process-level singletons (the kernel via registerWorker,
//     the BM25 search index, the embedding/vector index). Per-file process
//     isolation guarantees one file's leftover singleton state can never bleed
//     into another's, which matters for the parity / e2e files that boot a
//     real kernel + libSQL store + HTTP server.
//   - testTimeout: a margin above the default for the e2e file, which opens a
//     node:http server on an ephemeral port and round-trips fetch() calls.
//   - setupFiles: isolate the suite from the developer's real ~/.memwarden —
//     see test/setup.ts. Without it, a machine that has run `memwarden up`
//     fails 21 tests on unmodified code.
//
// No reporters/coverage are configured: the suite is dependency-free beyond
// what package.json already declares (vitest, tsx, typescript).

import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    include: ["test/**/*.test.ts"],
    pool: "forks",
    setupFiles: ["test/setup.ts"],
    testTimeout: 20_000,
    hookTimeout: 20_000,
  },
});

import { describe, expect, it } from "vitest";
import {
  QUANTILE_METHOD,
  sampleMedian,
  sampleQuantileR7,
} from "../eval/memory-halflife-statistics.js";

describe("memory half-life summary statistics", () => {
  it("uses the middle observation as the median for an odd sample", () => {
    expect(sampleMedian([9, 1, 5])).toBe(5);
  });

  it("averages the two middle observations as the median for an even sample", () => {
    expect(sampleMedian([4, 1, 3, 2])).toBe(2.5);
  });

  it("implements R-7 linear interpolation for quartiles", () => {
    expect(QUANTILE_METHOD).toBe("R7_LINEAR_INTERPOLATION");
    expect(sampleQuantileR7([1, 2, 3, 4], 0.25)).toBe(1.75);
    expect(sampleQuantileR7([1, 2, 3, 4], 0.75)).toBe(3.25);
  });

  it("handles endpoints and does not mutate the caller's sample", () => {
    const values = [3, 1, 2];
    expect(sampleQuantileR7(values, 0)).toBe(1);
    expect(sampleQuantileR7(values, 1)).toBe(3);
    expect(values).toEqual([3, 1, 2]);
  });

  it("rejects empty, non-finite, and out-of-range inputs", () => {
    expect(() => sampleMedian([])).toThrow(/at least one/);
    expect(() => sampleMedian([1, Number.NaN])).toThrow(/finite sample/);
    expect(() => sampleQuantileR7([1], -0.01)).toThrow(/\[0, 1\]/);
    expect(() => sampleQuantileR7([1], 1.01)).toThrow(/\[0, 1\]/);
  });
});
